<script setup lang="ts">
import { onMounted, ref } from 'vue';import { apiSeguridad } from '@/utils/seguridad'
const roles=ref<any[]>([]),permisos=ref<any[]>([]),nombre=ref(''),descripcion=ref(''),seleccionados=ref<number[]>([]),error=ref('');const cargar=async()=>{try{[roles.value,permisos.value]=await Promise.all([apiSeguridad('/roles'),apiSeguridad('/permisos')])}catch(e:any){error.value=e.message}};const guardar=async()=>{try{await apiSeguridad('/roles',{method:'POST',body:JSON.stringify({nombre:nombre.value,descripcion:descripcion.value,permiso_ids:seleccionados.value})});nombre.value=descripcion.value='';seleccionados.value=[];cargar()}catch(e:any){error.value=e.message}};onMounted(cargar)
</script><template><div class="admin-page"><section class="page-hero admin-hero d-flex align-center ga-4 mb-6"><VAvatar color="primary" variant="tonal" rounded size="58"><VIcon icon="tabler-shield-check" size="30"/></VAvatar><div><div class="process-kicker">Seguridad y acceso</div><h1 class="text-h4 font-weight-bold mb-1">Roles</h1><p class="text-medium-emphasis mb-0">Define responsabilidades y agrupa permisos del sistema.</p></div></section><VRow><VCol cols="12" lg="4"><VCard class="module-card h-100"><VCardItem class="module-header"><VCardTitle>Nuevo rol</VCardTitle><VCardSubtitle>Configura un perfil de acceso</VCardSubtitle></VCardItem><VCardText class="pa-6"><VAlert v-if="error" type="error" variant="tonal" class="mb-4">{{error}}</VAlert><VTextField v-model="nombre" label="Nombre del rol" prepend-inner-icon="tabler-id" class="mb-3"/><VTextField v-model="descripcion" label="Descripción" prepend-inner-icon="tabler-notes" class="mb-3"/><VSelect v-model="seleccionados" :items="permisos" item-title="descripcion" item-value="id" label="Permisos" multiple chips prepend-inner-icon="tabler-key"/><VBtn block size="large" prepend-icon="tabler-plus" class="mt-5" @click="guardar">Crear rol</VBtn></VCardText></VCard></VCol><VCol cols="12" lg="8"><VCard class="module-card h-100"><VCardItem class="module-header"><VCardTitle>Roles configurados</VCardTitle><template #append><VChip color="primary" variant="tonal">{{roles.length}} roles</VChip></template></VCardItem><VCardText class="pa-6"><VDataTable :items="roles" :headers="[{title:'Empresa',key:'empresa_id'},{title:'Departamento',key:'departamento'},{title:'Rol',key:'nombre'},{title:'Descripción',key:'descripcion'},{title:'Estado',key:'estado'}]" class="product-table"><template #item.empresa_id="{item}">{{item.empresa_id||'General'}}</template><template #item.departamento="{item}">{{item.departamento||'General'}}</template><template #item.nombre="{item}"><strong>{{item.nombre}}</strong></template><template #item.estado="{item}"><VChip size="small" :color="String(item.estado).toLowerCase()==='activo'?'success':'secondary'" variant="tonal">{{item.estado}}</VChip></template></VDataTable></VCardText></VCard></VCol></VRow></div></template>
